syntax:
```c++
template <typename T> class X { /* ... */ };

// Explicit instantiation of X<int> and X<double>
template class X<int>;
template class X<double>;

// Function template explicit instantiation
template <typename T> T max(T a, T b) { return (a > b) ? a : b; }
template int max<int>(int, int); //only int version instantiated
```

code_example:
#include <iostream>
#include <vector>
template <typename T>
class MyClass {
public:
  std::vector<T> data;
  MyClass(const std::vector<T>& d) : data(d) {}
  void print() {
    for (const auto& item : data) {
      std::cout << item << " ";
    }
    std::cout << std::endl;
  }
};
// Explicit instantiation for int and double
template class MyClass<int>;
template class MyClass<double>;
int main() {
  std::vector<int> intData = {1, 2, 3};
  MyClass<int> intObj(intData);
  intObj.print(); //This will work because of explicit instantiation
  //MyClass<std::string> stringObj; //This will fail to compile unless explicitly instantiated
  return 0;
}
